parameters.jsCode:
// ====== CONFIGURAÇÃO ======
const LIMITE_VAGAS = 20;     // quantas vagas NOVAS vão para a IA por execução (Groq grátis)
const DESCRICAO_MAX = 1000;  // caracteres da descrição enviados à IA

// Memória de vagas já avaliadas (dedupe entre execuções).
// Só é gravada em execução de produção (schedule); em teste manual nada é salvo.
const sd = $getWorkflowStaticData('global');
const jaVistas = new Set(sd.linkedinVistos || []);

// Tira acentos e deixa minúsculo (estágio -> estagio)
const norm = (s) => (s || '').toString().toLowerCase()
  .normalize('NFD').replace(/[̀-ͯ]/g, '');

// 1. O título precisa ter pelo menos um destes termos (área)
const areasFoco = [
  // dados
  'dados', 'data', 'analytics', 'bi', 'business intelligence', 'power bi', 'python', 'sql',
  // suporte / TI geral
  'suporte', 'service desk', 'help desk', 'helpdesk', 'ti', 'it support',
  'tecnologia da informacao', 'sistema', 'operacoes de ti',
  // QA
  'qa', 'teste', 'tester', 'qualidade de software', 'quality assurance',
  // desenvolvimento
  'desenvolvedor', 'desenvolvimento de software', 'developer', 'software', 'programador'
];

// 2. Descarta pelo título: senioridade e gestão
const termosDescarte = [
  'senior', 'sr', 'pleno', 'especialista', 'ii', 'iii', 'iv',
  'lead', 'leader', 'lider', 'head', 'staff', 'principal', 'arquiteto',
  'coordenador', 'gerente', 'manager', 'director', 'diretor', 'supervisor'
];

// Termos curtos (até 4 letras) só valem como palavra inteira
const contem = (titulo, lista) => lista.some(termo => {
  if (termo.length <= 4) {
    return new RegExp('(^|[^a-z0-9])' + termo + '([^a-z0-9]|$)').test(titulo);
  }
  return titulo.includes(termo);
});

// Link sem parâmetros de rastreio (?position=...&trackingId=...)
const linkLimpo = (u) => (u || '').toString().split('?')[0];

// ID da vaga: campo id do Apify ou o número no final do link
const idDaVaga = (j) => {
  if (j.id) return String(j.id);
  const m = linkLimpo(j.link || j.url).match(/(\d{6,})\/?$/);
  return m ? m[1] : linkLimpo(j.link || j.url);
};

// Local padronizado: "Belo Horizonte, Minas Gerais, Brazil" -> "Belo Horizonte, MG"
const localLimpo = (s) => {
  let t = (s || '').toString().trim();
  if (/greater belo horizonte/i.test(t)) return 'Belo Horizonte e região';
  t = t.replace(/,\s*Brazil$/i, '').replace(/Minas Gerais/i, 'MG');
  return t || 'Não informado';
};

// Remove repetidas dentro da mesma execução e as já avaliadas em execuções anteriores
const nestaExecucao = new Set();
const novas = $input.all().filter(item => {
  const id = idDaVaga(item.json);
  if (!id) return false;
  if (nestaExecucao.has(id) || jaVistas.has(id)) return false;
  nestaExecucao.add(id);
  return true;
});

// Filtro de título (área + senioridade)
const vagasFiltradas = novas.filter(item => {
  const titulo = norm(item.json.title);
  return contem(titulo, areasFoco) && !contem(titulo, termosDescarte);
});

return vagasFiltradas.slice(0, LIMITE_VAGAS).map(item => {
  const descricaoCompleta = (item.json.description || item.json.descriptionText || '').toString();
  return {
    json: {
      ...item.json,
      jobId: idDaVaga(item.json),
      link: linkLimpo(item.json.link || item.json.url),
      location: localLimpo(item.json.location),
      descricaoTamanho: descricaoCompleta.trim().length,
      description: descricaoCompleta.slice(0, DESCRICAO_MAX)
    }
  };
});

// Roda uma vez por vaga, dentro do Loop.
// A IA só classifica; a NOTA é calculada aqui, sempre pela mesma regra.
const limpa = (s) => (s || '').toString().replace(/[*_`\[\]]/g, '').trim();
const limpaLista = (v) => (Array.isArray(v) ? v : (v ? [v] : []))
  .map(limpa).filter(x => x && x !== '...').slice(0, 5);

// 1. Texto gerado pelo Basic LLM Chain
let rawText = ($json.text || '').toString();
rawText = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();
const inicio = rawText.indexOf('{');
const fim = rawText.lastIndexOf('}');
if (inicio !== -1 && fim > inicio) rawText = rawText.slice(inicio, fim + 1);

let ia = null;
try { ia = JSON.parse(rawText); } catch (e) { ia = null; }

// 2. Dados originais da vaga que está passando pelo Loop agora
let job = {};
try { job = $('Loop Over Items').item.json; } catch (e) { job = {}; }

// 3. Cálculo da nota (0 a 100)
//    Área até 35 + Nível até 25 + Requisitos até 40
const PONTOS_AREA  = { dados: 35, suporte_qa_ti: 28, desenvolvimento: 20, fora_de_ti: 0 };
const PONTOS_NIVEL = { estagio: 25, trainee: 25, junior: 20, nao_informado: 12, pleno_ou_acima: 0 };
const NOME_NIVEL   = { estagio: 'estágio', trainee: 'trainee', junior: 'júnior', nao_informado: 'nível não informado', pleno_ou_acima: 'pleno ou acima' };
const NOME_AREA    = { dados: 'dados', suporte_qa_ti: 'suporte/QA/TI', desenvolvimento: 'desenvolvimento', fora_de_ti: 'fora de TI' };

// Belo Horizonte e região metropolitana
const RMBH = ['belo horizonte', 'contagem', 'betim', 'nova lima', 'vespasiano', 'lagoa santa',
  'sabara', 'santa luzia', 'ribeirao das neves', 'ibirite', 'confins', 'pedro leopoldo', 'brumadinho'];
const norm = (s) => (s || '').toString().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');

let score = 0, nivel = '', area = '', avisos = [], erroIA = false;
let atendidos = [], faltantes = [], pontos = [], resumo = '';

if (!ia) {
  erroIA = true;
  resumo = 'Erro ao processar a resposta da IA';
} else {
  nivel = PONTOS_NIVEL[ia.nivel] !== undefined ? ia.nivel : 'nao_informado';
  area = PONTOS_AREA[ia.area] !== undefined ? ia.area : 'fora_de_ti';
  atendidos = limpaLista(ia.requisitos_atendidos);
  faltantes = limpaLista(ia.requisitos_faltantes);
  pontos = limpaLista(ia.pontos_fortes).slice(0, 4);
  resumo = limpa(ia.resumo_vaga);

  const totalReq = atendidos.length + faltantes.length;
  const ptsReq = totalReq === 0 ? 20 : Math.round(40 * atendidos.length / totalReq);
  score = PONTOS_AREA[area] + PONTOS_NIVEL[nivel] + ptsReq;

  // Tetos
  const local = norm(job.location);
  const modalidade = (ia.modalidade || '').toString();
  const naRegiao = RMBH.some(c => local.includes(c));
  const localGenerico = !local || local === 'nao informado' || local === 'brazil' || local === 'brasil';
  const localOk = naRegiao || modalidade === 'remoto' || localGenerico;
  const descricaoCurta = (job.descricaoTamanho || 0) < 400 || ia.descricao_suficiente === false;

  if (nivel === 'pleno_ou_acima') { score = Math.min(score, 40); avisos.push('Pede pleno/sênior ou mais de 2 anos de experiência'); }
  if (area === 'fora_de_ti')     { score = Math.min(score, 30); avisos.push('Vaga fora de TI'); }
  if (!localOk)                  { score = Math.min(score, 30); avisos.push('Presencial/híbrido fora de BH e região'); }
  if (descricaoCurta)            { score = Math.min(score, 70); avisos.push('Descrição curta: nota limitada a 70 (avaliada pelo título)'); }
}

// 4. Marca a vaga como avaliada (dedupe). Se a IA falhou, NÃO marca: tenta de novo amanhã.
if (!erroIA && job.jobId) {
  const sd = $getWorkflowStaticData('global');
  const lista = sd.linkedinVistos || [];
  if (!lista.includes(job.jobId)) lista.push(job.jobId);
  sd.linkedinVistos = lista.slice(-5000);
}

const totalReq = atendidos.length + faltantes.length;
return {
  json: {
    jobId: job.jobId || '',
    title: limpa(job.title) || 'Título não informado',
    company: limpa(job.companyName) || 'Empresa não informada',
    location: limpa(job.location) || 'Não informado',
    url: job.link || job.url || '',
    score,
    nivel: NOME_NIVEL[nivel] || '',
    area: NOME_AREA[area] || '',
    requisitosResumo: totalReq ? `${atendidos.length}/${totalReq} requisitos` : 'requisitos não listados',
    avisos,
    erroIA,
    pontos_fortes: pontos,
    requisitos_atendidos: atendidos,
    requisitos_faltantes: faltantes,
    resumo_vaga: resumo
  }
};

