// Monta a mensagem final do Telegram (HTML) com carta, bullets e link limpo.
const v = $('Code in JavaScript1').item.json;

const esc = (s) => (s || '').toString()
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const bullets = (lista, vazio) => (lista && lista.length)
  ? lista.map(x => '• ' + esc(x)).join('\n')
  : '• ' + vazio;

// Carta: a IA escreve só o meio; saudação, apresentação e assinatura são fixas
let corpo = ($json.text || '').toString()
  .replace(/[*_`#]/g, '')
  .split('\n')
  .filter(l => !/^\s*(olá|ola|prezad|atenciosamente|seu nome|github\.com)/i.test(l))
  .join(' ')
  .replace(/^\s*(sou|me chamo|meu nome é)\s+seu nome[^.]*\.\s*/i, '')
  .replace(/\s+/g, ' ')
  .trim();

const carta = corpo
  ? 'Olá,\n\nSou SEU NOME, SUA FORMAÇÃO (ex.: curso e ano). '
    + corpo
    + '\n\nAtenciosamente,\nSEU NOME\ngithub.com/SEU-USUARIO'
  : '(não foi possível gerar a carta desta vez)';

const cor = v.score >= 80 ? '🟢' : '🟡';
const detalhes = [v.nivel, v.area, v.requisitosResumo].filter(Boolean).join(' · ');
const avisos = (v.avisos || []).map(a => '⚠️ <i>' + esc(a) + '</i>').join('\n');

const linhas = [
  '🎯 <b>NOVA VAGA COMPATÍVEL</b>',
  '📌 <b>Vaga:</b> ' + esc(v.title),
  '🏢 <b>Empresa:</b> ' + esc(v.company),
  '📍 <b>Local:</b> ' + esc(v.location),
  cor + ' <b>Score:</b> ' + v.score + '/100  <i>(' + esc(detalhes) + ')</i>',
];
if (avisos) linhas.push(avisos);
linhas.push(
  '',
  '💡 <b>Resumo:</b> ' + esc(v.resumo_vaga || 'Sem resumo.'),
  '',
  '✅ <b>Pontos fortes:</b>',
  bullets(v.pontos_fortes, 'Nenhum identificado'),
  '',
  '❗ <b>Requisitos faltantes:</b>',
  bullets(v.requisitos_faltantes, 'Nenhum identificado na descrição'),
  '',
  '✉️ <b>Sugestão de carta:</b>',
  '',
  esc(carta),
  '',
  '🔗 <a href="' + esc(v.url) + '">Abrir a vaga no LinkedIn</a>'
);

return { json: { mensagem: linhas.join('\n') } };
